        Assert.assertEquals(COMMENT+format.getCommentStart()+format.getRecordSeparator(),appendable.toString());
    }

    @Test
    public void testPrintln_PrintRecordSeparator()throws Exception{
        instance.println();
        Assert.assertEquals(format.getRecordSeparator(),appendable.toString());
    }

    @Test
    public void testPrintRecord_Iterable_PrintValues()throws Exception{
