public class ExtendedBufferedReaderTest{
private ExtendedBufferedReader extendedBufferedReader;
    private Reader reader;
    private final String cr = "\r";
    private final String lf = "\n";
    private final String crlf = cr+lf;
    private final String CRLF = crlf.toUpperCase();

    @Before
    public void setUp() throws IOException {
        reader = new java.io.StringReader(cr);
        extendedBufferedReader = new ExtendedBufferedReader(reader);
    }

    @After
    public void tearDown() throws IOException {
        extendedBufferedReader.close();
    }

    @Test
    public void testRead() throws Exception {
        int actual = extendedBufferedReader.read();
        Assert.assertEquals('\r', actual);
        Assert.assertEquals(1, extendedBufferedReader.getLineNumber());
    }

    @Test
    public void testMultipleReads() throws Exception {
        reader = new java.io.StringReader(crlf);
        extendedBufferedReader = new ExtendedBufferedReader(reader);
        int actual = extendedBufferedReader.read();
        Assert.assertEquals('\r', actual);
        actual = extendedBufferedReader.read();
        Assert.assertEquals('\n', actual);
        Assert.assertEquals(1, extendedBufferedReader.getLineNumber());
    }

    @Test
    public void testLineCounter() throws Exception {
        reader = new java.io.StringReader(crlf+crlf+crlf);
        extendedBufferedReader = new ExtendedBufferedReader(reader);
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        Assert.assertEquals(3, extendedBufferedReader.getLineNumber());
    }

    @Test
    public void testLineCounterWithLF() throws Exception {
        reader = new java.io.StringReader(lf+lf+lf);
        extendedBufferedReader = new ExtendedBufferedReader(reader);
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        Assert.assertEquals(3, extendedBufferedReader.getLineNumber());
    }

    @Test
    public void testLineCounterWithCR() throws Exception {
        reader = new java.io.StringReader(cr+cr+cr);
        extendedBufferedReader = new ExtendedBufferedReader(reader);
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        extendedBufferedReader.read();
        Assert.assertEquals(3, extendedBufferedReader.getLineNumber());
    }

    @Test
    public void testEndOfStream() throws Exception {
        reader = new java.io.StringReader("");
        extendedBufferedReader = new ExtendedBufferedReader(reader);
        Assert.assertEquals(-1, extendedBufferedReader.read());
    }

    @Test
    public void testUndefinedLastChar() throws Exception {
        Assert.assertEquals(-2, extendedBufferedReader.lastChar);
    }
}
