import static org.hamcrest.Matchers.*;
import static org.apache.commons.csv.Constants.COMMENT;
import static org.apache.commons.csv.Constants.CR;
import static org.apache.commons.csv.Constants.LF;
import static org.apache.commons.csv.Constants.SP;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.sql.ResultSet;
import java.sql.SQLException;

public class CSVPrinterTest{
@Rule
    public ExpectedException expectedException = ExpectedException.none();
    private CSVPrinter printer;
    private StringWriter sw;

    @Before
    public void before(){
        sw = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT;
        printer = new CSVPrinter(sw, format);
    }

    @Test
    public void test_println_recordSeparator_null() throws Exception {
        CSVFormat format = CSVFormat.DEFAULT.withRecordSeparator((String) null);
        printer = new CSVPrinter(sw, format);
        printer.println();
        assertEquals("", sw.toString());
    }

    @Test
    public void test_println_recordSeparator_not_null() throws Exception {
        CSVFormat format = CSVFormat.DEFAULT.withRecordSeparator("\r\n");
        printer = new CSVPrinter(sw, format);
        printer.println();
        assertEquals("\r\n", sw.toString());
    }

    @Test
    public void test_println_newRecord_true() throws Exception {
        boolean newRecordBefore = printer.newRecord;
        printer.println();
        assertEquals(true, printer.newRecord);
        assertEquals(newRecordBefore, true);
    }

    @Test
    public void test_println_newRecord_false() throws Exception {
        printer.newRecord = false;
        printer.println();
        assertEquals(true, printer.newRecord);
    }

    @Test
    public void test_close() throws Exception {
        printer.close();
        assertThat(sw.toString(), is(""));
    }

    @Test
    public void test_flush() throws Exception {
        printer.print("test");
        printer.flush();
        assertThat(sw.toString(), is("test"));
    }

    @Test
    public void test_getOut() throws Exception {
        assertThat(printer.getOut(), instanceOf(StringWriter.class));
    }

    @Test
    public void test_print() throws Exception {
        printer.print("test");
        assertThat(sw.toString(), is("test"));
    }

    @Test
    public void test_print_comment() throws Exception {
        printer.printComment(COMMENT + "test");
        assertThat(sw.toString(), is(COMMENT + "test"));
    }

    @Test
    public void test_printRecord_iterable() throws Exception {
        printer.printRecord(java.util.Arrays.asList("test1", "test2"));
        assertThat(sw.toString(), is("test1,test2" + LF));
    }

    @Test
    public void test_printRecord_objects() throws Exception {
        printer.printRecord("test1", "test2");
        assertThat(sw.toString(), is("test1,test2" + LF));
    }

    @Test
    public void test_printRecords_iterable() throws Exception {
        printer.printRecords(java.util.Arrays.asList("test1", "test2"));
        assertThat(sw.toString(), is("test1,test2" + LF));
    }

    @Test
    public void test_printRecords_objects() throws Exception {
        printer.printRecords("test1", "test2");
        assertThat(sw.toString(), is("test1,test2" + LF));
    }

    @Test
    public void test_printRecords_resultSet() throws Exception {
        ResultSet resultSet = mock(ResultSet.class);
        when(resultSet.next()).thenReturn(true).thenReturn(false);
        when(resultSet.getString(1)).thenReturn("test1").thenReturn("test2");
        printer.printRecords(resultSet);
        assertThat(sw.toString(), is("test1,test2" + LF));
    }

    @After
    public void after() throws Exception {
        printer.close();
    }
}
